@push('scripts')<script>$(function(){var tableElement=$('#purchase-requisitions-table'),filters=$('#pr-filters'),text=$.fn.dataTable.render.text(),statuses={DRAFT:'app-status-neutral',SUBMITTED:'app-status-warning',APPROVED:'app-status-success',REJECTED:'app-status-danger',VOID:'app-status-danger'};window.erpInitSelect2('#pr-filter-supplier',{placeholder:'ค้นหา Supplier',allowClear:true,ajax:{url:$('#pr-filter-supplier').data('url'),delay:250,data:function(p){return{q:p.term||'',page:p.page||1};},processResults:function(data){return data;}}});var table=tableElement.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:'{{ route('purchasing.purchase-requisitions.data') }}',data:function(data){data.document_date_from=$('#pr-filter-date-from').val();data.document_date_to=$('#pr-filter-date-to').val();data.supplier_id=$('#pr-filter-supplier').val();data.status=$('#pr-filter-status').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton(tableElement)],columns:[{data:'document_number',name:'document_number',render:function(value,type,row){return type==='display'?'<a class="fw-semibold link-primary" href="'+text.display(row.show_url)+'">'+text.display(value)+'</a>':value;}},{data:'document_date_label',name:'document_date',render:text.display},{data:'supplier_label',name:'supplier_id',render:text.display},{data:'purchase_order_label',name:'purchase_order_id',render:text.display},{data:'description',name:'description',defaultContent:'-',render:text.display},{data:'status_label',name:'status',render:function(value,type,row){return type==='display'?'<span class="badge '+(statuses[row.status]||'app-status-neutral')+'">'+text.display(value)+'</span>':row.status;}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(value,type,row){if(type!=='display')return '';var actions=['<a class="btn btn-sm btn-app-soft" href="'+text.display(row.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-file-find" aria-hidden="true"></i></a>'];if(row.edit_url)actions.push('<a class="btn btn-sm btn-app-soft" href="'+text.display(row.edit_url)+'" title="แก้ไข" aria-label="แก้ไข"><i class="bx bx-edit" aria-hidden="true"></i></a>');if(row.print_url)actions.push('<a class="btn btn-sm btn-app-soft" target="_blank" href="'+text.display(row.print_url)+'" title="พิมพ์" aria-label="พิมพ์"><i class="bx bx-printer" aria-hidden="true"></i></a>');if(row.delete_url)actions.push('<button type="button" class="btn btn-sm btn-app-danger js-pr-delete" data-url="'+text.display(row.delete_url)+'" title="ลบร่าง" aria-label="ลบร่าง"><i class="bx bx-trash" aria-hidden="true"></i></button>');return actions.join(' ');}}]}));filters.on('change','input,select',function(){table.ajax.reload();});filters.on('click','.js-filter-reset',function(){$('#pr-filter-date-from,#pr-filter-date-to,#pr-filter-status').val('');$('#pr-filter-supplier').val(null).trigger('change');table.ajax.reload();});window.erpAjaxDelete({button:'.js-pr-delete',reload:'#purchase-requisitions-table',title:'ลบร่างใบขอซื้อ?',text:'เอกสารร่างจะถูกลบและไม่สามารถกู้คืนได้',confirmButtonText:'ลบร่าง',cancelButtonText:'กลับ'});});</script>@endpush
